INSERT INTO `Notice` VALUES (1,'2025-05-08 02:20:37','2025-05-08 02:20:37','세종대왕',NULL,'조선의 제4대 국왕이다.'),(2,'2025-05-08 02:20:37','2025-05-08 02:20:37','단군',NULL,'단군왕검(檀君王儉)은 한민족의 시조이자 고조선(古朝鮮)의 국조(國祖), 대종교의 시작.'),(3,'2025-05-08 02:20:37','2025-05-08 02:20:37','정약용',NULL,'조선 후기의 문신이자 실학자·저술가·시인·철학자·과학자·공학자이다.'),(4,'2025-05-08 02:20:37','2025-05-08 02:20:37','계백',NULL,'백제 말기의 군인이다.'),(5,'2025-05-08 02:20:37','2025-05-08 02:20:37','이순신',NULL,'조선 중기의 무신이었다. 본관은 덕수(德水), 자는 여해(汝諧), 시호는 충무(忠武).'),(6,'2025-05-08 02:20:37','2025-05-08 02:20:37','김유신',NULL,'신라의 화랑의 우두머리였으며 태대각간(太大角干)이었고 신라에 귀순한 가야 왕족의 후손.');
/*!40000 ALTER TABLE `Notice` ENABLE KEYS */;
