    (SELECT FORMAT(AVG(salary) * 10000, 0) FROM Emp WHERE dept = d.id) avgsal
        FROM Dept d INNER JOIN Emp e 
          ON d.id = e.dept AND d.captain = e.id
      WHERE d.dname LIKE concat(_dept_name, '%');
END ;;
